pm.test("Status 201 en login", function () {
  pm.expect(pm.response.code).to.eql(201);
});
const json = pm.response.json();
pm.test("Devuelve access_token", function () {
  pm.expect(json).to.have.property("access_token");
  pm.expect(json.access_token).to.be.a("string");
  pm.environment.set("authToken", json.access_token);
});
pm.test("Usuario presente", function () {
  pm.expect(json.user).to.have.property("email");
});

pm.test("GET /sedes devuelve 200", function () {
  pm.expect(pm.response.code).to.eql(200);
});
const json = pm.response.json();
pm.test("Respuesta es un array", function () {
  pm.expect(Array.isArray(json)).to.eql(true);
  pm.expect(json.length).to.be.greaterThan(0);
});
if (Array.isArray(json) && json.length > 0) {
  pm.environment.set("sedeId", json[0].id);
}

pm.test("Reserva creada con 201", function () {
  pm.expect(pm.response.code).to.eql(201);
});
const json = pm.response.json();
pm.test("Reserva con ID y estado válido", function () {
  pm.expect(json).to.have.property("id");
  pm.expect(json).to.have.property("estado");
  pm.expect(json.estado).to.be.oneOf(["pendiente", "confirmada"]);
  pm.environment.set("reservaId", json.id);
});

pm.test("Se rechaza con conflicto 409", function () {
  pm.expect(pm.response.code).to.eql(409);
});
const json = pm.response.json();
pm.test("Mensaje de sobreventa o turno ocupado", function () {
  pm.expect(json).to.have.property("message");
  const msg = String(json.message).toLowerCase();
  pm.expect(msg).to.match(/ya está reservado|ocupado|en mantenimiento|inactiva/i);
});
